from pathlib import Path
import re

app=Path('CaddieOS/App.js')
text=app.read_text()

def must(old,new,label):
    global text
    if old not in text:
        raise SystemExit(f'Build 61 patch marker missing: {label}')
    text=text.replace(old,new,1)

# Remove Build 60 auto-save-on-every-keystroke behaviour.
text,n=re.subn(r"\n useEffect\(\(\)=>\{if\(!course\.trim\(\)\)return;setSavedCourses\(prev=>\{const entry=\{name:course\.trim\(\),tee,targets\};const i=prev\.findIndex\(x=>x\.name\.toLowerCase\(\)===entry\.name\.toLowerCase\(\)\);const next=i>=0\?prev\.map\(\(x,k\)=>k===i\?entry:x\):\[entry,\.\.\.prev\]\.slice\(0,50\);return JSON\.stringify\(next\)===JSON\.stringify\(prev\)\?prev:next\}\)\},\[course,tee,targets\]\);",'',text,count=1)
if n!=1: raise SystemExit('Build 61: failed to remove Build 60 autosave')

# Pass wind data into Round so the visual meter and caddie math agree.
must("gpsLive={gpsLive} startLiveGPS={startLiveGPS} stopLiveGPS={stopLiveGPS} targetDistances={targetDistances}","gpsLive={gpsLive} startLiveGPS={startLiveGPS} stopLiveGPS={stopLiveGPS} targetDistances={targetDistances} wind={wind} windDir={windDir}",'Round wind props')

# Responsive header: no clipped ANTI-GLARE badge on phone widths.
text,n=re.subn(r"function Header\(\{go\}\)\{.*?\nfunction BottomNav",'''function Header({go}){return <View style={[s.header,{paddingHorizontal:12,gap:8}]}><TouchableOpacity onPress={go} style={{flex:1,minWidth:0}}><Text style={s.brand} numberOfLines={1}>CADDIE<Text style={s.brandGold}>OS</Text></Text><Text style={[s.brandSub,{fontSize:9}]} numberOfLines={1}>TOUR-LEVEL DECISIONS · YOUR GAME</Text></TouchableOpacity><View style={{flexShrink:0,borderWidth:1,borderColor:C.gold,borderRadius:12,paddingHorizontal:8,paddingVertical:5}}><Text style={[s.anti,{fontSize:9}]} numberOfLines={1}>ANTI-GLARE</Text></View></View>}
function BottomNav''',text,count=1,flags=re.S)
if n!=1: raise SystemExit('Build 61: Header replacement failed')

# Round: 18 holes, live GPS, live visual hole map and visual wind meter.
round_rx=r"function Round\(\{hole,setHole,result,units,gps,gpsLive,startLiveGPS,stopLiveGPS,targetDistances,open\}\)\{.*?\nfunction Caddie"
round_new='''function Round({hole,setHole,result,units,gps,gpsLive,startLiveGPS,stopLiveGPS,targetDistances,wind,windDir,open}){const holes=Array.from({length:18},(_,i)=>String(i+1)),arrow=windDir==='HEAD'?'↓':windDir==='TAIL'?'↑':windDir==='L→R'?'→':'←',windType=windDir==='HEAD'?'HEADWIND':windDir==='TAIL'?'TAILWIND':'CROSSWIND';return <><Title kicker="ROUND" title={`Hole ${hole}`} sub={gpsLive?`LIVE GPS${gps?.acc?` · ±${gps.acc} m`:''}`:'GPS ready when you are'}/><View style={{flexDirection:'row',flexWrap:'wrap',gap:5,marginBottom:9}}>{holes.map(x=><TouchableOpacity key={x} onPress={()=>setHole(x)} style={{width:'15.2%',minHeight:34,borderRadius:8,alignItems:'center',justifyContent:'center',backgroundColor:String(hole)===x?C.gold:'#153348',borderWidth:1,borderColor:String(hole)===x?C.gold:'#315064'}}><Text style={{fontSize:10,fontWeight:'900',color:String(hole)===x?C.dark:C.white}}>{x}</Text></TouchableOpacity>)}</View><View style={[s.panel,{padding:10}]}><View style={{flexDirection:'row',justifyContent:'space-between',alignItems:'center'}}><Text style={s.panelTitle}>LIVE HOLE MAP</Text><Text style={{fontSize:10,fontWeight:'900',color:gpsLive?C.blue:C.muted}}>{gpsLive?'● LIVE':'GPS OFF'}</Text></View><View style={{height:185,borderRadius:14,backgroundColor:'#173F35',borderWidth:2,borderColor:'#315D4E',overflow:'hidden',alignItems:'center'}}><View style={{position:'absolute',top:14,width:82,height:42,borderRadius:41,backgroundColor:C.green,borderWidth:3,borderColor:C.white}}/><View style={{position:'absolute',top:33,width:4,height:118,backgroundColor:'#B4C88A',opacity:.7}}/><View style={{position:'absolute',bottom:18,width:18,height:18,borderRadius:9,backgroundColor:C.gold,borderWidth:3,borderColor:C.white}}/><Text style={{position:'absolute',top:25,fontSize:16,fontWeight:'900',color:C.navy}}>⚑</Text><Text style={{position:'absolute',bottom:4,fontSize:9,fontWeight:'900',color:C.white}}>YOU</Text><View style={{position:'absolute',right:10,top:10,backgroundColor:'rgba(4,19,30,.82)',borderRadius:10,paddingHorizontal:9,paddingVertical:7,alignItems:'center'}}><Text style={{fontSize:27,fontWeight:'900',color:C.gold2}}>{arrow}</Text><Text style={{fontSize:13,fontWeight:'900',color:C.white}}>{wind||0} {units==='METRES'?'km/h':'mph'}</Text><Text style={{fontSize:9,fontWeight:'900',color:C.gold2}}>{windType}</Text></View></View></View><View style={s.panel}><Text style={s.panelTitle}>GREEN DISTANCES</Text><View style={s.distanceRow}><Stat a={targetDistances.front??'—'} b="FRONT"/><Stat a={targetDistances.center??'—'} b="CENTRE"/><Stat a={targetDistances.back??'—'} b="BACK"/></View><Text style={s.small}>{units==='METRES'?'metres':'yards'} · {gps?`${gps.lat}, ${gps.lon}`:'No position yet'}</Text></View><View style={s.panel}><Text style={s.panelTitle}>CADDIE RECOMMENDATION</Text><Text style={s.bigClub}>{result.club}</Text><Text style={s.cardSub}>Playing {result.y} {units==='METRES'?'m':'yd'} · {windType} {wind||0}</Text></View><Btn text={gpsLive?'STOP LIVE GPS':'START LIVE GPS'} onPress={gpsLive?stopLiveGPS:startLiveGPS}/><Btn text="OPEN CADDIE" onPress={()=>open('CADDIE')} outline/><Btn text="SCORE THIS HOLE" onPress={()=>open('SCORE')} outline/></>}
function Caddie'''
text,n=re.subn(round_rx,round_new,text,count=1,flags=re.S)
if n!=1: raise SystemExit('Build 61: Round replacement failed')

# Replace Course with explicit save flow. Directory selection populates the active course;
# manual name input appears only when MANUAL COURSE is selected.
course_rx=r"function Course\(\{course,setCourse,tee,setTee,hole,setHole,gps,getGPS,open,markTarget,currentTarget,targets,setTargets,savedCourses,setSavedCourses\}\)\{.*?\nfunction More"
course_new='''function Course({course,setCourse,tee,setTee,hole,setHole,gps,getGPS,open,markTarget,currentTarget,targets,setTargets,savedCourses,setSavedCourses}){
 const[q,setQ]=useState(''),[results,setResults]=useState([]),[searching,setSearching]=useState(false),[importing,setImporting]=useState(false),[manual,setManual]=useState(!course),[source,setSource]=useState(course?'saved':'manual');
 const norm=v=>String(v||'').trim().toLowerCase();
 const cleanCourses=a=>{const src=Array.isArray(a)?a.filter(x=>x&&String(x.name||'').trim()):[];const out=[];for(const x of src){const name=String(x.name).trim(),sameData=y=>(y.tee||'White')===(x.tee||'White')&&JSON.stringify(y.targets||[])===JSON.stringify(x.targets||[]);const longer=src.find(y=>y!==x&&norm(y.name).startsWith(norm(name))&&String(y.name).trim().length>name.length&&sameData(y));if(longer)continue;if(!out.some(y=>norm(y.name)===norm(name)))out.push({...x,name});}return out.slice(0,24)};
 useEffect(()=>{setSavedCourses(prev=>{const next=cleanCourses(prev);return JSON.stringify(next)===JSON.stringify(prev)?prev:next})},[]);
 const searchCourses=async()=>{const term=q.trim();if(term.length<2)return Alert.alert('Course search','Type at least two letters of the course name.');setSearching(true);try{const r=await fetch(`https://api.opengolfapi.org/v1/courses/search?q=${encodeURIComponent(term)}&limit=12`);if(!r.ok)throw new Error(`HTTP ${r.status}`);const j=await r.json();const a=Array.isArray(j)?j:(j?.courses||j?.results||j?.data||[]);setResults(Array.isArray(a)?a:[]);if(!a?.length)Alert.alert('Course search','No matching course found. Use MANUAL COURSE to map it yourself.')}catch(e){Alert.alert('Course search','The online course directory is unavailable right now. Manual setup still works.')}finally{setSearching(false)}};
 const point=v=>{if(!v||typeof v!=='object')return null;const lat=Number(v.lat??v.latitude??v.y),lon=Number(v.lon??v.lng??v.longitude??v.x);return Number.isFinite(lat)&&Number.isFinite(lon)?{lat,lon}:null};
 const holeTarget=h=>{const g=h?.green||h?.coordinates||h?.gps||{};return{front:point(h?.front||h?.green_front||h?.greenFront||g?.front),center:point(h?.center||h?.green_center||h?.greenCenter||h?.pin||g?.center||g?.green),back:point(h?.back||h?.green_back||h?.greenBack||g?.back)}};
 const selectCourse=async item=>{const id=item?.id??item?.course_id??item?.courseId;if(id===undefined||id===null)return Alert.alert('Course import','This course record has no usable ID.');setImporting(true);try{const [cr,hr,tr]=await Promise.all([fetch(`https://api.opengolfapi.org/v1/courses/${id}`),fetch(`https://api.opengolfapi.org/v1/courses/${id}/holes`),fetch(`https://api.opengolfapi.org/v1/courses/${id}/tees`)]);const c=cr.ok?await cr.json():item,hj=hr.ok?await hr.json():[],tj=tr.ok?await tr.json():[];const name=c?.name||c?.course_name||item?.name||item?.course_name||'Golf Course';setCourse(name);setSource('directory');setManual(false);const hs=Array.isArray(hj)?hj:(hj?.holes||hj?.data||[]);if(Array.isArray(hs)&&hs.length){const mapped=Array.from({length:18},(_,i)=>holeTarget(hs[i]||{}));if(mapped.some(x=>x.front||x.center||x.back))setTargets(mapped)}const tees=Array.isArray(tj)?tj:(tj?.tees||tj?.data||[]);if(Array.isArray(tees)&&tees.length){const preferred=tees.find(x=>String(x?.color||x?.name||'').toLowerCase()===String(tee).toLowerCase())||tees[0],raw=String(preferred?.color||preferred?.name||''),match=TEES.find(x=>x.toLowerCase()===raw.toLowerCase());if(match)setTee(match)}setResults([]);setQ('')}catch(e){Alert.alert('Course import','Could not import this course. Manual course setup is still available.')}finally{setImporting(false)}};
 const loadSaved=x=>{setCourse(x.name);setTee(x.tee||'White');setTargets(Array.isArray(x.targets)&&x.targets.length===18?x.targets:blankTargets());setHole('1');setSource('saved');setManual(false)};
 const saveCourse=()=>{const name=String(course||'').trim();if(!name)return Alert.alert('Save course','Select a course or enter a manual course name first.');const entry={name,tee,targets};setSavedCourses(prev=>{const clean=cleanCourses(prev),i=clean.findIndex(x=>norm(x.name)===norm(name));return i>=0?clean.map((x,k)=>k===i?entry:x):[entry,...clean].slice(0,24)});Alert.alert('Course saved',`${name} · ${tee} tee is saved in CaddieOS.`)};
 return <><Title kicker="MAP & PLAY" title="Course" sub={course?`${course} · ${tee} tee`:'Find or map your course'}/><Panel><Label text="COURSE DIRECTORY"/><View style={{flexDirection:'row',gap:7}}><TextInput value={q} onChangeText={setQ} onSubmitEditing={searchCourses} placeholder="Search course name" placeholderTextColor="#8A8F91" style={[s.input,{flex:1,marginBottom:0}]}/><TouchableOpacity onPress={searchCourses} disabled={searching} style={{backgroundColor:C.gold,borderRadius:10,paddingHorizontal:13,justifyContent:'center',opacity:searching?.65:1}}><Text style={{fontWeight:'900',color:C.text,fontSize:12}}>{searching?'SEARCHING':'SEARCH'}</Text></TouchableOpacity></View>{results.map((x,i)=>{const name=x?.name||x?.course_name||'Golf Course',place=[x?.city,x?.state,x?.country].filter(Boolean).join(', ');return <TouchableOpacity key={String(x?.id??x?.course_id??i)} onPress={()=>selectCourse(x)} style={{paddingVertical:9,borderTopWidth:1,borderTopColor:C.line}}><Text style={{color:C.text,fontWeight:'900'}}>{name}</Text>{place?<Text style={s.smallGrey}>{place}</Text>:null}</TouchableOpacity>})}{importing?<Text style={{color:C.gold,fontWeight:'900',marginTop:8}}>IMPORTING COURSE…</Text>:null}{savedCourses.length?<><Text style={[s.panelTitle,{marginTop:8}]}>SAVED COURSES · {savedCourses.length}</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{gap:6}}>{savedCourses.slice(0,8).map((x,i)=><TouchableOpacity key={`${norm(x.name)}-${i}`} onPress={()=>loadSaved(x)} style={{borderWidth:1,borderColor:norm(x.name)===norm(course)?C.gold:C.line,borderRadius:9,paddingHorizontal:10,paddingVertical:7,backgroundColor:norm(x.name)===norm(course)?C.panel2:C.white}}><Text numberOfLines={1} style={{fontSize:11,fontWeight:'900',color:C.text,maxWidth:145}}>{x.name}</Text></TouchableOpacity>)}</ScrollView></>:null}<TouchableOpacity onPress={()=>{setManual(true);setSource('manual');setCourse('');setTargets(blankTargets())}} style={{marginTop:9,alignSelf:'flex-start'}}><Text style={{fontSize:11,fontWeight:'900',color:C.blue}}>+ MANUAL COURSE</Text></TouchableOpacity></Panel><Panel>{manual?<><Label text="COURSE NAME"/><TextInput value={course} onChangeText={setCourse} placeholder="Enter course" placeholderTextColor="#8A8F91" style={s.input}/></>:<><Label text="SELECTED COURSE"/><Text style={{fontSize:18,fontWeight:'900',color:C.text,marginBottom:10}} numberOfLines={2}>{course||'No course selected'}</Text></>}<Label text="TEE"/><View style={s.chips}>{TEES.map(x=><Chip key={x} active={tee===x} text={x} onPress={()=>setTee(x)}/>)}</View><Btn text="SAVE COURSE" onPress={saveCourse}/></Panel><Panel><View style={s.holeTop}><View><Text style={s.holeLabel}>CURRENT HOLE</Text><Text style={s.holeBig}>{hole}</Text></View><View style={s.holeBtns}><Mini text="−" onPress={()=>setHole(String(Math.max(1,n(hole)-1)))}/><Mini text="+" onPress={()=>setHole(String(Math.min(18,n(hole)+1)))}/></View></View><TouchableOpacity style={s.gps} onPress={getGPS}><Text style={s.gpsText}>⌖  GET MAPPING GPS</Text></TouchableOpacity>{gps&&<Text style={s.gpsLine}>{gps.lat}, {gps.lon} · ±{gps.acc} m</Text>}<View style={s.divider}/><Text style={s.subTitle}>MAP GREEN · HOLE {hole}</Text><Text style={s.smallGrey}>Mapping GPS only: stand at Front, Centre and Back, then save each point.</Text><View style={s.mapBtns}>{['front','center','back'].map(k=><TouchableOpacity key={k} style={[s.mapBtn,currentTarget?.[k]&&s.mapBtnDone]} onPress={()=>markTarget(k)}><Text style={s.mapBtnTxt}>{k.toUpperCase()}</Text></TouchableOpacity>)}</View></Panel><TouchableOpacity style={s.infoBtn} onPress={()=>open('COURSEINFO')}><Text style={s.infoBtnText}>COURSE INFORMATION</Text></TouchableOpacity></>}

function More'''
text,n=re.subn(course_rx,course_new,text,count=1,flags=re.S)
if n!=1: raise SystemExit('Build 61: Course replacement failed')

# Build number.
gradle=Path('CaddieOS/android/app/build.gradle')
g=gradle.read_text()
g=re.sub(r'versionCode\s+\d+','versionCode 61',g)
g=re.sub(r'versionName\s+"[^"]+"','versionName "1.0.61"',g)
gradle.write_text(g)

app.write_text(text)
